update public.clinical_scale_definitions set definition=definition||jsonb_build_object('scoringStatus','ready','engineVersion','1.0','inputPolicy','explicit_values_only') where scale_key in ('sofa','apache-ii','braden','humpty-dumpty');
update public.clinical_scale_definitions set definition=definition||jsonb_build_object('domains',array['respiratory','coagulation','liver','cardiovascular','cns','renal'],'scoreRange',jsonb_build_array(0,24)) where scale_key='sofa';
update public.clinical_scale_definitions set definition=definition||jsonb_build_object('components',array['acute_physiology','age','chronic_health'],'scoreRange',jsonb_build_array(0,71),'measurementWindow','worst values during first 24 hours of ICU admission') where scale_key='apache-ii';
update public.clinical_scale_definitions set definition=definition||jsonb_build_object('domains',array['sensory_perception','moisture','activity','mobility','nutrition','friction_shear'],'scoreRange',jsonb_build_array(6,23)) where scale_key='braden';
update public.clinical_scale_definitions set definition=definition||jsonb_build_object('parameters',array['age','diagnosis','cognitive_impairment','environmental_factors','surgery_sedation_anesthesia'],'scoreRange',jsonb_build_array(5,20),'highRiskThreshold',12,'updatedAlgorithm',true) where scale_key='humpty-dumpty';